#!/bin/bash
# Builds build/windows/AiberTyper.exe (64-bit; Windows on ARM runs it emulated) from macOS, Linux or Windows (Git Bash).
# Needs Go only: the icon and manifest are generated by cmd/rsrc, then go build cross-compiles.
set -euo pipefail
cd "$(dirname "$0")"
go run ./cmd/rsrc ../../design/brand/icon-1024.png app/rsrc_windows_amd64.syso
mkdir -p ../../build/windows
GOOS=windows GOARCH=amd64 CGO_ENABLED=0 go build -trimpath -ldflags "-H windowsgui -s -w" -o ../../build/windows/AiberTyper.exe ./app
echo "Built build/windows/AiberTyper.exe"
